from datetime import date
from decimal import Decimal
import pytest
from src.revenue import RevenueCalculator


def test_simple_full_overlap():
    tx = {"start_date": date(2026, 7, 1), "end_date": date(2026, 7, 31), "amount": Decimal('310.00'), "currency": 'USD'}
    res = RevenueCalculator.calculate(date(2026,7,1), date(2026,7,31), [tx])
    assert res == {'USD': Decimal('310.00')}


def test_partial_overlap_proration():
    tx = {"start_date": date(2026, 7, 1), "end_date": date(2026, 7, 31), "amount": Decimal('310.00'), "currency": 'USD'}
    res = RevenueCalculator.calculate(date(2026,7,1), date(2026,7,16), [tx])
    assert res == {'USD': Decimal('160.00')}


def test_leap_year_feb29():
    tx = {"start_date": date(2020, 2, 1), "end_date": date(2020, 2, 29), "amount": Decimal('290.00'), "currency": 'USD'}
    res = RevenueCalculator.calculate(date(2020,2,1), date(2020,2,29), [tx])
    assert res == {'USD': Decimal('290.00')}


def test_transactions_outside_range_ignored():
    tx = {"start_date": date(2026, 6, 1), "end_date": date(2026, 6, 30), "amount": Decimal('300.00'), "currency": 'USD'}
    res = RevenueCalculator.calculate(date(2026,7,1), date(2026,7,31), [tx])
    assert res == {}


def test_mixed_currencies_grouping():
    tx1 = {"start_date": date(2026,7,1), "end_date": date(2026,7,31), "amount": Decimal('310.00'), "currency": 'USD'}
    tx2 = {"start_date": date(2026,7,1), "end_date": date(2026,7,31), "amount": Decimal('310.00'), "currency": 'EUR'}
    res = RevenueCalculator.calculate(date(2026,7,1), date(2026,7,31), [tx1, tx2])
    assert res == {'USD': Decimal('310.00'), 'EUR': Decimal('310.00')}


def test_negative_amounts_allowed_for_refunds():
    tx = {"start_date": date(2026,7,1), "end_date": date(2026,7,31), "amount": Decimal('-31.00'), "currency": 'USD'}
    res = RevenueCalculator.calculate(date(2026,7,1), date(2026,7,31), [tx])
    assert res == {'USD': Decimal('-31.00')}


def test_rounding_per_transaction():
    tx = {"start_date": date(2026,7,1), "end_date": date(2026,7,3), "amount": Decimal('1.00'), "currency": 'USD'}
    res = RevenueCalculator.calculate(date(2026,7,1), date(2026,7,1), [tx, tx, tx])
    assert res == {'USD': Decimal('0.99')}

