    tx = {"start_date": "2026-07-01", "end_date": "2026-07-01", "amount": Decimal('10.00'), "currency": 'USD'}
    with pytest.raises(ValueError):
        RevenueCalculator.calculate(date(2026,7,1), date(2026,7,1), [tx])


