import time
from datetime import date, timedelta
from decimal import Decimal
from src.revenue import RevenueCalculator


def make_tx(start, days, amount='10.00', currency='USD'):
    return {"start_date": start, "end_date": start + timedelta(days=days-1), "amount": Decimal(amount), "currency": currency}


def test_benchmark_large_dataset(benchmark=False):
    base = date(2026,7,1)
    n = 100000
    txs = [make_tx(base, 1) for _ in range(n)]
    start = time.time()
    res = RevenueCalculator.calculate(base, base, txs)
    elapsed = time.time() - start
    assert res['USD'] == Decimal('1000000.00')
    print(f"Processed {n} tx in {elapsed:.3f}s")

