from decimal import Decimal, ROUND_HALF_UP, InvalidOperation
from typing import Optional, Dict


def compute_standard_revenue(items: Dict[str, Dict], discount_pct: Optional[Decimal] = None, tax_pct: Optional[Decimal] = None) -> Decimal:
    """Compute standard revenue for an order.

    items: mapping item_id -> {"quantity": int, "unit_price": str/number/Decimal, "currency": str}
    discount_pct: percent as Decimal/number between 0 and 100 (e.g. Decimal('5.0') or 5 for 5%)
    tax_pct: percent as Decimal/number between 0 and 100

    Returns total revenue as Decimal rounded to 2 decimal places (cents) using ROUND_HALF_UP.

    Raises ValueError on invalid inputs (empty items, missing/invalid prices, non-integer/negative quantities, mismatched currencies, invalid percent ranges).

    Note: per-line rounding is intentionally NOT performed; the final total is rounded to 2 decimal places as a business rule.
    """
    if not items:
        raise ValueError("items must be a non-empty mapping")

    # Normalize and validate currencies: treat None and empty string as missing
    currencies = set()
    for meta in items.values():
        cur = meta.get("currency")
        if cur == "":
            cur = None
        currencies.add(cur)
    present_currencies = {c for c in currencies if c is not None}
    if len(present_currencies) > 1:
        raise ValueError(f"mismatched currencies: {sorted(present_currencies)}")

    # Helper to coerce percent-like inputs into Decimal and validate range
    def _coerce_percent(name: str, pct):
        if pct is None:
            return None
        try:
            pct_dec = Decimal(str(pct))
        except (InvalidOperation, TypeError, ValueError):
            raise ValueError(f"{name} must be a numeric value between 0 and 100")
        if pct_dec < 0 or pct_dec > 100:
            raise ValueError(f"{name} must be between 0 and 100")
        return pct_dec

    discount_pct = _coerce_percent("discount_pct", discount_pct)
    tax_pct = _coerce_percent("tax_pct", tax_pct)

    total = Decimal('0')
    for item_id, meta in items.items():
        qty = meta.get("quantity")
        # Enforce integer quantities for this domain
        if not isinstance(qty, int):
            raise ValueError(f"invalid quantity for item {item_id}: must be an integer >= 0")
        if qty < 0:
            raise ValueError(f"invalid quantity for item {item_id}")

        unit_price_raw = meta.get("unit_price")
        if unit_price_raw is None:
            raise ValueError(f"invalid price for item {item_id}")
        try:
            unit_price = Decimal(str(unit_price_raw))
        except (InvalidOperation, TypeError, ValueError):
            raise ValueError(f"invalid price for item {item_id}")
        if unit_price < 0:
            raise ValueError(f"invalid price for item {item_id}")

        total += unit_price * Decimal(qty)

    if discount_pct is not None:
        total *= (Decimal('100') - discount_pct) / Decimal('100')

    if tax_pct is not None:
        total *= (Decimal('100') + tax_pct) / Decimal('100')

    # Round to 2 decimal places (cents) using ROUND_HALF_UP
    total = total.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
    return total


