import pytest
from decimal import Decimal
from revenue.standard_revenue import compute_standard_revenue


def test_basic_single_item():
    items = {"a": {"quantity": 2, "unit_price": "10.00", "currency": "USD"}}
    assert compute_standard_revenue(items) == Decimal('20.00')


def test_discount_and_tax():
    items = {"a": {"quantity": 1, "unit_price": "100.00", "currency": "USD"}}
    # 10% discount then 5% tax: 100 * 0.9 * 1.05 = 94.5 -> 94.50
    assert compute_standard_revenue(items, discount_pct=Decimal('10'), tax_pct=Decimal('5')) == Decimal('94.50')


def test_percent_args_as_float_and_int():
    items = {"a": {"quantity": 1, "unit_price": "100.00", "currency": "USD"}}
    # Accept float/int percent args and coerce them correctly
    assert compute_standard_revenue(items, discount_pct=10.0, tax_pct=5) == Decimal('94.50')


def test_rounding():
    items = {"a": {"quantity": 1, "unit_price": "0.005", "currency": "USD"}}
    assert compute_standard_revenue(items) == Decimal('0.01')


@pytest.mark.parametrize("bad", [None, {}])
def test_invalid_inputs_empty(bad):
    with pytest.raises(ValueError):
        compute_standard_revenue(bad)


def test_negative_quantity():
    with pytest.raises(ValueError):
        compute_standard_revenue({"a": {"quantity": -1, "unit_price": "1.00"}})


def test_non_integer_quantity_raises():
    with pytest.raises(ValueError):
        compute_standard_revenue({"a": {"quantity": 2.5, "unit_price": "1.00"}})


def test_unit_price_none_raises():
    with pytest.raises(ValueError):
        compute_standard_revenue({"a": {"quantity": 1, "unit_price": None}})


def test_invalid_price_string_raises():
    with pytest.raises(ValueError):
        compute_standard_revenue({"a": {"quantity": 1, "unit_price": "abc"}})


def test_currency_mismatch_raises():
    items = {
        "a": {"quantity": 1, "unit_price": "1.00", "currency": "USD"},
        "b": {"quantity": 1, "unit_price": "1.00", "currency": "EUR"},
    }
    with pytest.raises(ValueError) as exc:
        compute_standard_revenue(items)
    assert "mismatched currencies" in str(exc.value)


# Keep previous parametrized test for backward compatibility
@pytest.mark.parametrize("bad", [{"a": {"quantity": -1, "unit_price": "1.00"}}])
def test_invalid_inputs_negative_quantity(bad):
    with pytest.raises(ValueError):
        compute_standard_revenue(bad)


