from typing import List, Dict, Any
import time
import logging
from .utils import normalize_to_cents, cents_to_decimal_str
from .rwlock import RWLock
from .pricing_client_interface import PricingServiceClient, PricingServiceError

logger = logging.getLogger(__name__)


class PricingTierCache:
    """Thread-safe cache for pricing tiers. Uses RWLock to allow many
    concurrent readers and exclusive writers when refreshing a tier.

    Cache entries: { product_id: (timestamp_monotonic, tier_dict) }
    """

    def __init__(self, client: PricingServiceClient, ttl_seconds: int = 60):
        self._client = client
        self._ttl = ttl_seconds
        self._cache: Dict[str, Any] = {}
        self._lock = RWLock()

    def get_tier(self, product_id: str) -> Dict[str, Any]:
        # Fast path: read lock, check freshness using monotonic timestamps
        self._lock.acquire_read()
        try:
            entry = self._cache.get(product_id)
            if entry and (time.monotonic() - entry[0]) < self._ttl:
                logger.debug("cache hit for product_id=%s", product_id)
                return entry[1]
        finally:
            self._lock.release_read()

        # Cache miss / stale entry: perform remote fetch OUTSIDE the write lock
        logger.debug("cache miss for product_id=%s; fetching from pricing service", product_id)
        try:
            tier = self._client.get_pricing_tier(product_id)
        except Exception as exc:
            # Do not cache on error; wrap and surface a domain-specific exception
            logger.exception("pricing fetch failed for product_id=%s", product_id)
            raise PricingServiceError(f"Failed to fetch pricing for product_id={product_id}") from exc

        # Basic validation of fetched data
        if not isinstance(tier, dict) or 'price' not in tier:
            logger.error("invalid tier format fetched for product_id=%s", product_id)
            raise PricingServiceError(f"Invalid tier data for product_id={product_id}")

        # Now safe to acquire write lock briefly and write the cache (double-check)
        self._lock.acquire_write()
        try:
            entry = self._cache.get(product_id)
            if entry and (time.monotonic() - entry[0]) < self._ttl:
                # Another thread refreshed while we were fetching
                logger.debug("another thread refreshed product_id=%s while fetching", product_id)
                return entry[1]

            # Commit fetched tier with monotonic timestamp
            self._cache[product_id] = (time.monotonic(), tier)
            logger.info("cached pricing tier for product_id=%s", product_id)
            return tier
        finally:
            self._lock.release_write()


class Calculator:
    def __init__(self, pricing_client: PricingServiceClient):
        self.pricing_cache = PricingTierCache(pricing_client)

    def calculate(self, invoice: Dict[str, Any]) -> Dict[str, Any]:
        """Public API: calculate totals for invoice.

        Invoice format:
          { 'items': [ { 'product_id': str, 'quantity': int, 'type': 'recurring'|'one-time', 'unit_price': optional(float|str|Decimal) } ] }

        Returns: { 'total_cents': int, 'total': '12.34' }

        Validation: raises ValueError for malformed client input and PricingServiceError
        for pricing service failures.
        """
        if 'items' not in invoice or not isinstance(invoice['items'], list):
            raise ValueError('invoice must contain items list')

        recurring_total = 0
        onetime_total = 0

        for i, item in enumerate(invoice['items']):
            if not isinstance(item, dict):
                raise ValueError(f'item at index {i} must be a mapping')

            # Quantity: require an integer >= 0
            if 'quantity' not in item:
                raise ValueError(f'item {i}: missing quantity')
            qty = item['quantity']
            if not isinstance(qty, int) or qty < 0:
                raise ValueError(f'item {i}: quantity must be an integer >= 0')

            item_type = item.get('type')
            if item_type not in ('recurring', 'one-time'):
                raise ValueError(f"item {i}: type must be 'recurring' or 'one-time'")

            unit_price_provided = 'unit_price' in item and item['unit_price'] is not None
            product_id = item.get('product_id')
            if not unit_price_provided and not product_id:
                raise ValueError(f'item {i}: product_id required when unit_price is not provided')

            # Determine unit price (may be provided or fetched from pricing service)
            if unit_price_provided:
                try:
                    unit_cents = normalize_to_cents(item['unit_price'])
                except Exception:
                    raise ValueError(f'item {i}: invalid unit_price')
            else:
                # May raise PricingServiceError which we let propagate to callers
                tier = self.pricing_cache.get_tier(product_id)
                unit_cents = normalize_to_cents(tier['price'])

            line_total = unit_cents * qty

            if item_type == 'recurring':
                recurring_total += line_total
            else:
                onetime_total += line_total

        grand_total = recurring_total + onetime_total
        return {
            'total_cents': grand_total,
            'total': cents_to_decimal_str(grand_total)
        }

