from typing import Optional, Dict, Any
import os
import time
import json
import requests
from requests import RequestException

# project.logging is the project's structured logging util
from project.logging import get_logger
# project.cache is a simple cache abstraction (e.g. Redis or memcache client wrapper)
from project import cache

logger = get_logger(__name__)

# Configuration (read from env; defaults chosen for safe behavior)
GATEWAY_URL = os.getenv('PAYMENT_GATEWAY_URL', 'https://api.payment-gateway.example/v1/pay')
GATEWAY_API_KEY = os.getenv('PAYMENT_GATEWAY_API_KEY')
IDEMPOTENCY_TTL_SECONDS = int(os.getenv('IDEMPOTENCY_TTL_SECONDS', '300'))  # 5 minutes default
IDEMPOTENCY_LOCK_TTL_SECONDS = int(os.getenv('IDEMPOTENCY_LOCK_TTL_SECONDS', '10'))  # lock TTL
IDEMPOTENCY_LOCK_WAIT_SECONDS = float(os.getenv('IDEMPOTENCY_LOCK_WAIT_SECONDS', '5.0'))  # how long to poll for cached result
MAX_RETRIES = int(os.getenv('PAYMENT_MAX_RETRIES', '3'))
BACKOFF_FACTOR = float(os.getenv('PAYMENT_BACKOFF_FACTOR', '0.5'))
REQUEST_TIMEOUT = float(os.getenv('PAYMENT_REQUEST_TIMEOUT', '5.0'))
CACHE_SET_RETRIES = 3


class PaymentError(Exception):
    pass


class PaymentProcessor:
    """Handles sending payment requests to the external gateway with idempotency and retries.

    Usage:
        processor = PaymentProcessor()
        result = processor.process_payment(amount=1200, currency='USD', customer_id='abc', idempotency_key='...')

    Notes:
        - Supports injection of an http client (requests.Session or compatible) for reuse/testing.
        - Cache helpers tolerate common cache client signatures (Redis 'set' with nx/ex, memcache 'add', or simple set(key, value, ttl=..)).
    """

    def __init__(self, gateway_url: str = GATEWAY_URL, api_key: Optional[str] = GATEWAY_API_KEY, http_client: Optional[Any] = None):
        self.gateway_url = gateway_url
        self.api_key = api_key
        if not self.api_key:
            logger.warning('Payment gateway API key is not set; calls will fail if gateway requires auth')
        # http_client should implement a .post(url, headers=..., json=..., timeout=...)
        self.http = http_client or requests.Session()

    def _validate_input(self, amount: int, currency: str, idempotency_key: Optional[str]) -> str:
        if not isinstance(amount, int) or amount <= 0:
            raise ValueError('amount must be a positive integer (cents)')
        if not isinstance(currency, str) or len(currency) != 3:
            raise ValueError('currency must be a 3-letter ISO code')
        if idempotency_key is not None and (not isinstance(idempotency_key, str) or len(idempotency_key) > 255):
            raise ValueError('idempotency_key must be a string <=255 chars')
        return currency.upper()

    def _cache_key(self, idempotency_key: str) -> str:
        return f'payment:idempotency:{idempotency_key}'

    def _backoff_sleep(self, attempt: int) -> None:
        # Exponential backoff: factor * (2 ** (attempt - 1))
        delay = BACKOFF_FACTOR * (2 ** (attempt - 1))
        logger.debug('Retry backoff', extra={'attempt': attempt, 'delay': delay})
        time.sleep(delay)

    # Helpers to abstract cache client's varying API signatures
    def _cache_get(self, key: str) -> Optional[str]:
        try:
            val = cache.get(key)
            if val is None:
                return None
            if isinstance(val, bytes):
                return val.decode('utf-8')
            return val
        except Exception:
            logger.exception('Failed to read from cache')
            return None

    def _cache_set_if_not_exists(self, key: str, value: str, ttl: int) -> bool:
        """Try common cache.set/add signatures to set value only if key does not exist.
        Returns True if the value was set, False if it already exists or could not be set.
        """
        # Try Redis-like set with nx/ex
        try:
            # many Redis wrappers return True when set with nx
            res = cache.set(key, value, nx=True, ex=ttl)
            if res is not None:
                return bool(res)
        except TypeError:
            # signature didn't accept nx/ex - try 'ttl' kwarg
            try:
                res = cache.set(key, value, ttl=ttl, nx=True)
                if res is not None:
                    return bool(res)
            except TypeError:
                # try memcache-like add(key, value, time)
                try:
                    if hasattr(cache, 'add'):
                        return bool(cache.add(key, value, ttl))
                except Exception:
                    logger.exception('Cache add failed')
                    return False
            except Exception:
                logger.exception('Cache set(nx,ttl) failed')
                return False
        except Exception:
            logger.exception('Cache set(nx,ex) failed')
            return False

        # If previous attempts returned None, fall back to plain set-if-not-exists behavior:
        try:
            existing = self._cache_get(key)
            if existing is not None:
                return False
            # attempt plain set with TTL
            try:
                cache.set(key, value, ttl=ttl)
                return True
            except TypeError:
                # other signature
                cache.set(key, value)
                # best-effort: cannot set TTL; return True
                return True
        except Exception:
            logger.exception('Fallback cache set-if-not-exists failed')
            return False

    def _cache_set_with_retries(self, key: str, value: str, ttl: int, retries: int = CACHE_SET_RETRIES) -> bool:
        last_exc = None
        for i in range(retries):
            try:
                # Prefer plain set that overwrites (we assume we hold the lock)
                try:
                    # try Redis signature with ex
                    res = cache.set(key, value, ex=ttl)
                    # if returns value or True, consider success
                    return True
                except TypeError:
                    try:
                        cache.set(key, value, ttl=ttl)
                        return True
                    except TypeError:
                        cache.set(key, value)
                        return True
            except Exception as e:
                last_exc = e
                logger.exception('cache.set attempt failed, will retry', extra={'attempt': i + 1})
                time.sleep(0.1 * (i + 1))
                continue
        if last_exc:
            logger.error('All cache.set retries failed')
            return False
        return False

    def _cache_delete(self, key: str) -> None:
        try:
            if hasattr(cache, 'delete'):
                cache.delete(key)
            else:
                # best-effort: try setting to empty with small ttl
                try:
                    cache.set(key, '', ttl=1)
                except Exception:
                    pass
        except Exception:
            logger.exception('Failed to delete cache key')

    def process_payment(self, amount: int, currency: str, customer_id: str, idempotency_key: Optional[str] = None, metadata: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
        """Process a single payment.

        - amount: integer amount in cents
        - currency: 3-letter currency code
        - customer_id: internal customer identifier
        - idempotency_key: optional key to make the operation idempotent across retries

        Returns the gateway response parsed as JSON on success.
        Raises PaymentError on unrecoverable errors.
        """
        currency = self._validate_input(amount, currency, idempotency_key)
        payload = {
            'amount': amount,
            'currency': currency,
            'customer_id': customer_id,
            'metadata': metadata or {},
        }

        headers = {
            'Content-Type': 'application/json',
        }
        if self.api_key:
            headers['Authorization'] = f'Bearer {self.api_key}'
        if idempotency_key:
            headers['Idempotency-Key'] = idempotency_key

        cache_key = None
        lock_key = None
        if idempotency_key:
            cache_key = self._cache_key(idempotency_key)
            lock_key = cache_key + ':lock'
            # fast-path: check cache
            try:
                cached = self._cache_get(cache_key)
            except Exception:
                cached = None
            if cached:
                logger.info('Idempotent response hit', extra={'idempotency_key': idempotency_key})
                try:
                    return json.loads(cached)
                except Exception:
                    logger.exception('Cached idempotent payload corrupted; proceeding to call gateway')

            # Try to acquire a short-lived distributed lock so only one caller hits the gateway
            acquired = self._cache_set_if_not_exists(lock_key, '1', ttl=IDEMPOTENCY_LOCK_TTL_SECONDS)
            if not acquired:
                # Another worker is processing the same idempotency key. Poll the cache for a short time for result.
                logger.debug('Could not acquire idempotency lock, polling for existing result', extra={'idempotency_key': idempotency_key})
                waited = 0.0
                poll_interval = 0.2
                while waited < IDEMPOTENCY_LOCK_WAIT_SECONDS:
                    try:
                        cached = self._cache_get(cache_key)
                        if cached:
                            try:
                                return json.loads(cached)
                            except Exception:
                                # corrupted cache - continue polling until timeout then proceed
                                logger.exception('Corrupted cached payload seen while waiting for in-progress payment')
                                return None
                    except Exception:
                        pass
                    time.sleep(poll_interval)
                    waited += poll_interval
                # If we reach here, proceed to call gateway (race risk exists but lock couldn't be acquired and no cached value ended up appearing)
                logger.warning('Proceeding to call gateway after lock-wait timeout; duplicate charge risk', extra={'idempotency_key': idempotency_key})

        last_exc = None
        for attempt in range(1, MAX_RETRIES + 1):
            try:
                logger.info('Sending payment request', extra={'amount': amount, 'currency': currency, 'attempt': attempt})
                resp = self.http.post(self.gateway_url, headers=headers, json=payload, timeout=REQUEST_TIMEOUT)
                # Treat 5xx as transient
                if 500 <= resp.status_code < 600:
                    raise RequestException(f'Gateway 5xx: {resp.status_code}')

                # 4xx indicates client error - do not retry
                if 400 <= resp.status_code < 500:
                    # Avoid logging raw response body (may contain sensitive data). Log status and gateway request id if present.
                    gw_req_id = resp.headers.get('X-Request-Id') if hasattr(resp, 'headers') else None
                    logger.error('Payment gateway returned client error', extra={'status': resp.status_code, 'gateway_request_id': gw_req_id})
                    raise PaymentError(f'Gateway client error: {resp.status_code}')

                # Success
                try:
                    data = resp.json()
                except ValueError:
                    logger.error('Invalid JSON from gateway', extra={'status': resp.status_code})
                    raise PaymentError('Invalid response from payment gateway')

                # Persist idempotent result (best-effort but retried). If persistence fails repeatedly we raise to avoid silent duplicate-charge windows.
                if cache_key:
                    try:
                        set_ok = self._cache_set_with_retries(cache_key, json.dumps(data), ttl=IDEMPOTENCY_TTL_SECONDS)
                        if not set_ok:
                            # Release lock before failing
                            try:
                                self._cache_delete(lock_key)
                            except Exception:
                                logger.exception('Failed to delete lock after unsuccessful cache persistence')
                            logger.error('Failed to persist idempotency result after successful gateway call')
                            raise PaymentError('Payment succeeded but failed to persist idempotency state; manual reconciliation required')
                    finally:
                        # Always attempt to release the lock
                        try:
                            self._cache_delete(lock_key)
                        except Exception:
                            logger.exception('Failed to delete idempotency lock')

                logger.info('Payment processed successfully', extra={'gateway_id': data.get('id')})
                return data

            except RequestException as e:
                last_exc = e
                logger.warning('Transient error when calling payment gateway', extra={'error': str(e), 'attempt': attempt})
                if attempt < MAX_RETRIES:
                    self._backoff_sleep(attempt)
                    continue
                else:
                    logger.error('Exceeded max retries for payment gateway')
                    raise PaymentError('Failed to process payment after retries') from e

            except PaymentError:
                # client or parsing errors - do not retry
                raise

            except Exception as e:
                logger.exception('Unexpected error in payment processing')
                raise PaymentError('Unexpected error during payment processing') from e

        # If we get here, raise last exception
        if last_exc:
            raise PaymentError('Failed to process payment') from last_exc
        raise PaymentError('Failed to process payment for unknown reasons')

