class DummyCache:
    def __init__(self):
        self._store = {}
        self.last_set_args = None

    def get(self, key):
        return self._store.get(key)

    def set(self, key, value, ttl=None, nx=False, ex=None):
        # support multiple signatures used by the implementation
        # if nx is True, set only if key does not exist
        self.last_set_args = {'key': key, 'value': value, 'ttl': ttl, 'nx': nx, 'ex': ex}
        if nx:
            if key in self._store:
                return False
            self._store[key] = value
            return True
        # normal set
        self._store[key] = value
        return True

    def add(self, key, value, time=0):
        # memcache-like add
        if key in self._store:
            return False
        self._store[key] = value
        return True

    def delete(self, key):
        self._store.pop(key, None)


