@patch('src.payment.processor.requests.Session.post')
def test_lock_and_concurrent_requests_integration(mock_post, patch_cache):
    # Ensure when two threads call with same tenant/customer/idempotency_key, only one gateway call happens
    from threading import Thread
    calls = []
    def gateway():
        mock_resp = MagicMock()
        mock_resp.status_code = 200
        mock_resp.json.return_value = {'id': 'gw_multi', 'status': 'succeeded', 'metadata': {}}
