from typing import Optional, Dict, Any, Callable
import os
import time
import json
import hmac
import hashlib
import requests
from requests import RequestException

# project.logging is the project's structured logging util
from project.logging import get_logger
# project.cache is a simple cache abstraction (e.g. Redis or memcache client wrapper)
from project import cache

logger = get_logger(__name__)

# Environment/runtime
RUNNING_ENV = os.getenv('RUNNING_ENV', 'dev')

# Configuration (read from env; defaults chosen for safe behavior)
GATEWAY_URL = os.getenv('PAYMENT_GATEWAY_URL', 'https://api.payment-gateway.example/v1/pay')
GATEWAY_API_KEY = os.getenv('PAYMENT_GATEWAY_API_KEY')
IDEMPOTENCY_TTL_SECONDS = int(os.getenv('IDEMPOTENCY_TTL_SECONDS', '300'))  # 5 minutes default
IDEMPOTENCY_LOCK_TTL_SECONDS = int(os.getenv('IDEMPOTENCY_LOCK_TTL_SECONDS', '10'))  # lock TTL
IDEMPOTENCY_LOCK_WAIT_SECONDS = float(os.getenv('IDEMPOTENCY_LOCK_WAIT_SECONDS', '5.0'))
MAX_RETRIES = int(os.getenv('PAYMENT_MAX_RETRIES', '3'))
BACKOFF_FACTOR = float(os.getenv('PAYMENT_BACKOFF_FACTOR', '0.5'))
REQUEST_TIMEOUT = float(os.getenv('PAYMENT_REQUEST_TIMEOUT', '5.0'))
CACHE_SET_RETRIES = int(os.getenv('CACHE_SET_RETRIES', '3'))

# Security / operational config
IDEMPOTENCY_HMAC_SECRET = os.getenv('IDEMPOTENCY_HMAC_SECRET')  # REQUIRED in prod
PAYMENT_FAIL_ON_PERSISTENCE_FAILURE = os.getenv('PAYMENT_FAIL_ON_PERSISTENCE_FAILURE', 'true').lower() in ('1','true','yes')
PAYMENT_METADATA_MAX_BYTES = int(os.getenv('PAYMENT_METADATA_MAX_BYTES', '4096'))

# Fail-fast if secret missing in production
if RUNNING_ENV == 'production' and not IDEMPOTENCY_HMAC_SECRET:
    raise RuntimeError('IDEMPOTENCY_HMAC_SECRET must be set in production')

# Allowed keys we will persist to cache from gateway responses
_CACHED_ALLOWLIST = {'id', 'status', 'gateway_request_id', 'created_at', 'metadata_summary'}


class PaymentError(Exception):
    pass


class PaymentProcessor:
    """Handles sending payment requests to the external gateway with idempotency and retries.

    tenant_resolver: callable that returns authoritative tenant_id for current request/context.
    """

    def __init__(self, gateway_url: str = GATEWAY_URL, api_key: Optional[str] = GATEWAY_API_KEY, http_client: Optional[Any] = None, tenant_resolver: Optional[Callable[[], str]] = None):
        self.gateway_url = gateway_url
        self.api_key = api_key
        if not self.api_key:
            logger.warning('Payment gateway API key is not set; calls may fail if gateway requires auth')
        self.http = http_client or requests.Session()
        self.tenant_resolver = tenant_resolver
        # In production, tenant_resolver should be provided; otherwise calls that rely on authoritative tenant fail.
        if RUNNING_ENV == 'production' and not callable(self.tenant_resolver):
            raise RuntimeError('tenant_resolver must be provided in production to obtain authoritative tenant identity')

    # ----------------- helpers: hashing/HMAC, logging-safe hash -----------------
    def _hmac_hex(self, value: str) -> str:
        """Return hex HMAC of value using IDEMPOTENCY_HMAC_SECRET."""
        secret = IDEMPOTENCY_HMAC_SECRET or ''
        hm = hmac.new(secret.encode('utf-8'), value.encode('utf-8'), hashlib.sha256)
        return hm.hexdigest()

    def _short_hash_for_log(self, value: str) -> str:
        return self._hmac_hex(value)[:8]

    # ----------------- cache key derivation (HMACed + tenant scoping) -----------------
    def _derive_cache_key(self, tenant_id: str, customer_id: str, idempotency_key: str) -> str:
        """Derive a cache key scoped to tenant and customer using HMAC to avoid raw-key reuse/guessing.

        Format: payment:idempotency:<hex-hmac>
        HMAC input: f"{tenant_id}:{customer_id}:{idempotency_key}"
        """
        input_str = f"{tenant_id}:{customer_id}:{idempotency_key}"
        hex_hmac = self._hmac_hex(input_str)
        return f'payment:idempotency:{hex_hmac}'

    # ----------------- cache helpers and normalization -----------------
    def _is_cache_success(self, res: Any) -> bool:
        if res in (True, 1, b'OK', 'OK'):
            return True
        if res is None:
            return False
        try:
            return bool(res)
        except Exception:
            return False

    def _cache_get(self, key: str) -> Optional[str]:
        try:
            val = cache.get(key)
            if val is None:
                return None
            if isinstance(val, bytes):
                return val.decode('utf-8')
            return val
        except Exception:
            logger.exception('Failed to read from cache')
            return None

    def _cache_set_if_not_exists(self, key: str, value: str, ttl: int) -> bool:
        try:
            res = cache.set(key, value, nx=True, ex=ttl)
            return self._is_cache_success(res)
        except TypeError:
            try:
                res = cache.set(key, value, ttl=ttl, nx=True)
                return self._is_cache_success(res)
            except TypeError:
                try:
                    if hasattr(cache, 'add'):
                        res = cache.add(key, value, ttl)
                        return self._is_cache_success(res)
                except Exception:
                    logger.exception('Cache add failed')
                    return False
            except Exception:
                logger.exception('Cache set(nx,ttl) failed')
                return False
        except Exception:
            logger.exception('Cache set(nx,ex) failed')
            return False
        # fallback
        try:
            existing = self._cache_get(key)
            if existing is not None:
                return False
            try:
                res = cache.set(key, value, ttl=ttl)
                if self._is_cache_success(res):
                    return True
            except TypeError:
                res = cache.set(key, value)
                if hasattr(cache, 'expire'):
                    exp_res = cache.expire(key, ttl)
                    return self._is_cache_success(exp_res)
                return self._is_cache_success(res)
        except Exception:
            logger.exception('Fallback cache set-if-not-exists failed')
            return False
        return False

    def _cache_set_with_retries(self, key: str, value: str, ttl: int, retries: int = CACHE_SET_RETRIES) -> bool:
        last_exc = None
        for i in range(retries):
            try:
                try:
                    res = cache.set(key, value, ex=ttl)
                    if self._is_cache_success(res):
                        return True
                except TypeError:
                    try:
                        res = cache.set(key, value, ttl=ttl)
                        if self._is_cache_success(res):
                            return True
                    except TypeError:
                        res = cache.set(key, value)
                        if hasattr(cache, 'expire'):
                            exp_ok = cache.expire(key, ttl)
                            if self._is_cache_success(exp_ok):
                                return True
                        if self._is_cache_success(res):
                            return True
            except Exception as e:
                last_exc = e
                logger.exception('cache.set attempt failed, will retry', extra={'attempt': i + 1})
                time.sleep(0.1 * (i + 1))
                continue
        if last_exc:
            logger.error('All cache.set retries failed')
            return False
        return False

    def _cache_delete(self, key: str) -> None:
        try:
            if hasattr(cache, 'delete'):
                cache.delete(key)
            else:
                try:
                    cache.set(key, '', ttl=1)
                except Exception:
                    pass
        except Exception:
            logger.exception('Failed to delete cache key')

    # ----------------- sanitization -----------------
    def sanitize_gateway_response(self, resp_json: Dict[str, Any]) -> Dict[str, Any]:
        sanitized: Dict[str, Any] = {}
        if not isinstance(resp_json, dict):
            return {}
        if 'id' in resp_json:
            sanitized['id'] = resp_json['id']
        if 'status' in resp_json:
            sanitized['status'] = resp_json['status']
        if 'gateway_request_id' in resp_json:
            sanitized['gateway_request_id'] = resp_json['gateway_request_id']
        if 'created_at' in resp_json:
            sanitized['created_at'] = resp_json['created_at']
        metadata = resp_json.get('metadata')
        if isinstance(metadata, dict):
            sanitized['metadata_summary'] = {'num_keys': len(metadata), 'total_bytes_est': sum(len(str(v)) for v in metadata.values())}
        else:
            sanitized['metadata_summary'] = {'num_keys': 0, 'total_bytes_est': 0}
        return sanitized

    # ----------------- input validation helpers -----------------
    def _validate_input(self, amount: int, currency: str, idempotency_key: Optional[str]) -> str:
        if not isinstance(amount, int) or amount <= 0:
            raise ValueError('amount must be a positive integer (cents)')
        if not isinstance(currency, str) or len(currency) != 3:
            raise ValueError('currency must be a 3-letter ISO code')
        if idempotency_key is not None and (not isinstance(idempotency_key, str) or len(idempotency_key) > 255):
            raise ValueError('idempotency_key must be a string <=255 chars')
        if idempotency_key is not None:
            import re
            if not re.match(r'^[A-Za-z0-9_\-+=]+$', idempotency_key):
                raise ValueError('idempotency_key contains invalid characters')
        return currency.upper()

    # ----------------- main flow -----------------
    def process_payment(self, amount: int, currency: str, customer_id: str, idempotency_key: Optional[str] = None, metadata: Optional[Dict[str, Any]] = None, tenant_id: Optional[str] = None) -> Dict[str, Any]:
        # Derive authoritative tenant from resolver if present
        authoritative_tenant = None
        if callable(self.tenant_resolver):
            try:
                authoritative_tenant = self.tenant_resolver()
            except Exception:
                logger.exception('tenant_resolver failed')
                raise PaymentError('Failed to resolve tenant identity')
        # If caller provided tenant_id, require it matches authoritative resolver (if resolver exists)
        if authoritative_tenant and tenant_id and tenant_id != authoritative_tenant:
            raise ValueError('tenant_id does not match authoritative tenant')
        # Use authoritative if available, else fallback to provided tenant_id
        tenant_id = authoritative_tenant or tenant_id
        if not tenant_id:
            raise ValueError('tenant_id is required to scope idempotency')

        currency = self._validate_input(amount, currency, idempotency_key)
        if metadata is not None:
            try:
                metadata_bytes = len(json.dumps(metadata).encode('utf-8'))
            except Exception:
                metadata_bytes = 0
            if metadata_bytes > PAYMENT_METADATA_MAX_BYTES:
                raise ValueError('metadata exceeds maximum allowed size')

        payload = {'amount': amount, 'currency': currency, 'customer_id': customer_id, 'metadata': metadata or {}}

        headers = {'Content-Type': 'application/json'}
        if self.api_key:
            headers['Authorization'] = f'Bearer {self.api_key}'
        if idempotency_key:
            headers['Idempotency-Key'] = idempotency_key

        cache_key = None
        lock_key = None
        lock_acquired = False

        if idempotency_key:
            cache_key = self._derive_cache_key(tenant_id, customer_id, idempotency_key)
            lock_key = cache_key + ':lock'
            try:
                cached_raw = self._cache_get(cache_key)
            except Exception:
                cached_raw = None
            if cached_raw:
                try:
                    cached_obj = json.loads(cached_raw)
                except Exception:
                    logger.exception('Cached idempotent payload corrupted; proceeding to call gateway', extra={'cache_key': cache_key})
                    cached_obj = None
                if cached_obj:
                    meta = cached_obj.get('_meta', {})
                    # compare tenant_id and a hashed customer identifier to avoid raw PII in cache metadata
                    if meta.get('tenant_id') == tenant_id and meta.get('customer_hash') == self._short_hash_for_log(customer_id):
                        logger.info('Idempotent response hit', extra={'idempotency_key_hash': cache_key[-8:], 'customer_hash': meta.get('customer_hash')})
                        return cached_obj['result']
                    else:
                        logger.warning('Cache hit with mismatched tenant/customer - ignoring', extra={'cache_meta': meta})

            lock_acquired = self._cache_set_if_not_exists(lock_key, '1', ttl=IDEMPOTENCY_LOCK_TTL_SECONDS)
            if not lock_acquired:
                logger.debug('Could not acquire idempotency lock, polling for cached result', extra={'idempotency_key_hash': cache_key[-8:]})
                waited = 0.0
                poll_interval = 0.2
                while waited < IDEMPOTENCY_LOCK_WAIT_SECONDS:
                    try:
                        cached_raw = self._cache_get(cache_key)
                    except Exception:
                        cached_raw = None
                    if cached_raw:
                        try:
                            cached_obj = json.loads(cached_raw)
                            meta = cached_obj.get('_meta', {})
                            if meta.get('tenant_id') == tenant_id and meta.get('customer_hash') == self._short_hash_for_log(customer_id):
                                logger.info('Idempotent response appeared while polling', extra={'idempotency_key_hash': cache_key[-8:]})
                                return cached_obj['result']
                        except Exception:
                            logger.exception('Corrupted cached payload seen while waiting for in-progress payment')
                    time.sleep(poll_interval)
                    waited += poll_interval
                logger.warning('Proceeding to call gateway after lock-wait timeout; duplicate charge risk', extra={'idempotency_key_hash': cache_key[-8:]})

        last_exc = None
        try:
            for attempt in range(1, MAX_RETRIES + 1):
                try:
                    logger.info('Sending payment request', extra={'amount': amount, 'currency': currency, 'attempt': attempt, 'customer_hash': self._short_hash_for_log(customer_id)})
                    resp = self.http.post(self.gateway_url, headers=headers, json=payload, timeout=REQUEST_TIMEOUT)
                    if 500 <= resp.status_code < 600:
                        raise RequestException(f'Gateway 5xx: {resp.status_code}')
                    if 400 <= resp.status_code < 500:
                        gw_req_id = resp.headers.get('X-Request-Id') if hasattr(resp, 'headers') else None
                        logger.error('Payment gateway returned client error', extra={'status': resp.status_code, 'gateway_request_id': gw_req_id})
                        raise PaymentError(f'Gateway client error: {resp.status_code}')
                    try:
                        data = resp.json()
                    except ValueError:
                        logger.error('Invalid JSON from gateway', extra={'status': resp.status_code})
                        raise PaymentError('Invalid response from payment gateway')

                    sanitized = self.sanitize_gateway_response(data)
                    cached_payload = {'_meta': {'tenant_id': tenant_id, 'customer_hash': self._short_hash_for_log(customer_id)}, 'result': sanitized}

                    if cache_key:
                        set_ok = self._cache_set_with_retries(cache_key, json.dumps(cached_payload), ttl=IDEMPOTENCY_TTL_SECONDS)
                        if not set_ok:
                            logger.error('Failed to persist idempotency result after successful gateway call')
                            if PAYMENT_FAIL_ON_PERSISTENCE_FAILURE:
                                raise PaymentError('Payment succeeded but failed to persist idempotency state; manual reconciliation required')
                            else:
                                logger.warning('Continuing despite idempotency persistence failure (best-effort mode)')

                    logger.info('Payment processed successfully', extra={'gateway_id': sanitized.get('id')})
                    return sanitized

                except RequestException as e:
                    last_exc = e
                    logger.warning('Transient error when calling payment gateway', extra={'error': str(e), 'attempt': attempt})
                    if attempt < MAX_RETRIES:
                        self._backoff_sleep(attempt)
                        continue
                    else:
                        logger.error('Exceeded max retries for payment gateway')
                        raise PaymentError('Failed to process payment after retries') from e

                except PaymentError:
                    raise

                except Exception as e:
                    logger.exception('Unexpected error in payment processing')
                    raise PaymentError('Unexpected error during payment processing') from e
        finally:
            if cache_key and lock_key and lock_acquired:
                try:
                    self._cache_delete(lock_key)
                except Exception:
                    logger.exception('Failed to delete idempotency lock')

        if last_exc:
            raise PaymentError('Failed to process payment') from last_exc
        raise PaymentError('Failed to process payment for unknown reasons')


